using HRIS.Api.Controllers; using HRIS.Api.DTOs.Family; using HRIS.Api.DTOs.Reference; using HRIS.Api.Exceptions; using HRIS.Api.Services; using HRIS.Api.Repositories; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages;
namespace HRIS.Api.Pages.Family; [Authorize(AuthenticationSchemes="Cookies")] public class IndexModel:PageModel { private readonly IFamilyChangeService _service; private readonly IReferenceService _refs; private readonly IEmployeeRepository _employees; public IndexModel(IFamilyChangeService service,IReferenceService refs,IEmployeeRepository employees){_service=service;_refs=refs;_employees=employees;} public List<FamilyChangeResponseDto> Items{get;set;}=new(); public List<EmployeeFamilyOption> Families{get;set;}=new(); public List<ReferenceItemDto> Relationships{get;set;}=new(); public List<ReferenceItemDto> Genders{get;set;}=new(); public async Task OnGetAsync(){var actor=User.ToUserContext();Items=await _service.GetAsync(actor);if(actor.EmployeeId is int id){var e=await _employees.GetByIdAsync(id);Families=e?.Families.Where(x=>true).Select(x=>new EmployeeFamilyOption(x.Id,x.FamilyName,x.Relationship?.RelationshipName??"-")).ToList()??new();}Relationships=await _refs.GetOptionsAsync("relationship");Genders=await _refs.GetOptionsAsync("gender");} public async Task<IActionResult> OnPostSaveAsync(string action,int? familyId,string familyName,int relationshipId,int? genderId,DateOnly? birthDate,bool isDependent,DateOnly? weddingDate){try{await _service.CreateAsync(new FamilyChangeCreateDto{Action=action,FamilyId=familyId,FamilyName=familyName,RelationshipId=relationshipId,GenderId=genderId,BirthDate=birthDate,IsDependent=isDependent,WeddingDate=weddingDate},User.ToUserContext());TempData["Success"]="Pengajuan perubahan data keluarga dibuat.";}catch(Exception ex)when(ex is BadRequestException or ForbiddenException or NotFoundException){TempData["Error"]=ex.Message;}return RedirectToPage();} } public record EmployeeFamilyOption(int Id,string FamilyName,string RelationshipName);
